@Entity
public class Order {
    @Id private OrderId id;
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true)
    private List<OrderLine> lines = new ArrayList<>();
    private long totalCents, creditLimitCents;
    public void addLine(OrderLine line) {
        if (totalCents + line.amountCents() > creditLimitCents) throw new LimitExceededException();
        lines.add(line); totalCents += line.amountCents();
    }
    public List<OrderLine> lines() { return List.copyOf(lines); }
}

